  async recordRepositoryInitializationCommit(eventId:string,receipt:RepositoryInitialCommit):Promise<void>{new RepositoryInitializationIntents(this.ctx.storage).recordCommit(eventId,receipt);}
  async markRepositoryInitializationPushPossible(eventId:string,actorId:string,credential:TaskCreationCredential):Promise<boolean>{await this.authorizeRepositoryInitialization(eventId,actorId,credential);const assert=await this.accountInitializationFence(actorId,credential);return new RepositoryInitializationIntents(this.ctx.storage).beginPush(eventId,assert);}
  async beginRepositoryInitializationReadCredential(eventId:string,actorId:string,credential:TaskCreationCredential):Promise<boolean>{await this.authorizeRepositoryInitialization(eventId,actorId,credential);const record=await this.repositoryInitializationRecord(eventId,actorId,credential);if(!record)throw Error("Saved empty initialization unavailable");const assert=await this.accountInitializationFence(actorId,credential,record.scope.projectId);assert();return new RepositoryInitializationIntents(this.ctx.storage).beginReadCredential(eventId,assert);}
