  async confirmRepositoryInitializationCredentialRevoked(eventId:string,token?:string):Promise<boolean>{const ledger=new RepositoryInitializationIntents(this.ctx.storage),record=ledger.get(eventId);if(!record)return false;const scope={eventId,allocationId:record.scope.allocationId,projectId:record.scope.projectId,incarnation:record.scope.incarnation,canonicalRepoName:record.scope.canonicalRepoName,accountKey:record.scope.accountKey,actorId:record.scope.actorId};if(ledger.credentials.settled(scope))return true;if(token)await ledger.credentials.record(scope,token);const pending=ledger.credentials.credentialForRevocation(eventId);return pending?ledger.confirmCredentialRevoked(eventId,pending.token,{repoName:record.scope.canonicalRepoName,revoked:true}):false;}
