    const incarnation=this.readRepositoryIncarnation();if(incarnation&&incarnation!==scope.incarnation)throw Error("Repository initialization incarnation changed");this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS repository_initialization_receipts(event_id TEXT PRIMARY KEY,payload TEXT NOT NULL)");const payload=JSON.stringify(record),old=this.ctx.storage.sql.exec<{payload:string}>("SELECT payload FROM repository_initialization_receipts WHERE event_id=?",scope.eventId).toArray()[0];if(old){if(old.payload!==payload)throw Error("Repository initialization receipt changed");return this.load();}
