  // ---- GitHub mirror (per project) ----
  private mirrorConfiguration(){const row=this.ctx.storage.sql.exec<{target:string;token:string;enabled:number;created_at:string}>("SELECT target,token,enabled,created_at FROM mirror WHERE id=1").toArray()[0];if(!row||validateMirrorTarget(row.target)!==row.target)throw Error("Approved normalized mirror configuration unavailable");return row;}
  private async mirrorConfigurationDigest(){const captured=JSON.stringify(this.mirrorConfiguration()),digest=Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(captured))),value=>value.toString(16).padStart(2,"0")).join("");if(JSON.stringify(this.mirrorConfiguration())!==captured)throw Error("Mirror configuration changed during authorization");return digest;}
  private mirrorAcceptedIdentity(journalId?:string){const state=this.load(),branch=state.defaultBranch;if(!branch||!isSafeRef(branch)||branch.startsWith("refs/"))throw Error("Recorded primary mirror branch unavailable");const ref=`refs/heads/${branch}`,head=state.acceptedState.currentCommit;if(head===null)throw Error("No accepted commit available to mirror");const journals=state.journal.filter(j=>j.state==="ACCEPTED"&&(!j.acceptedTarget||j.acceptedTarget.ref===ref)&&state.acceptedState.history.some(item=>item.candidateId===j.candidateId&&item.commit===j.newHead));const journal=journalId&&journalId!=="baseline"?journals.find(j=>j.id===journalId):journalId?undefined:journals.findLast(j=>j.newHead===head);if(journal){if(!journal.candidateTree||!isSafeSha(journal.candidateTree))throw Error("Recorded accepted mirror tree unavailable");return{journalId:journal.id,acceptedRef:ref,commit:journal.newHead,tree:journal.candidateTree};}const baseline=state.acceptedBaseline;if((!journalId||journalId==="baseline")&&baseline&&(journalId==="baseline"||baseline.commit===head)&&baseline.tree&&isSafeSha(baseline.tree))return{journalId:"baseline",acceptedRef:ref,commit:baseline.commit,tree:baseline.tree};throw Error("Exact accepted mirror receipt unavailable");}
