  async prepareMirrorExecutionForWorkflow(workflowId:string,journalId:string){const caller:MirrorAuthority={kind:"integration",workflowId,journalId},authority=await this.mirrorCallerAuthority(caller),state=this.load();this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS mirror_integration_requests(project_id TEXT NOT NULL,incarnation TEXT NOT NULL,workflow_id TEXT NOT NULL,journal_id TEXT NOT NULL,operation_id TEXT UNIQUE NOT NULL,PRIMARY KEY(project_id,incarnation,workflow_id,journal_id))");const old=this.ctx.storage.sql.exec<{operation_id:string}>("SELECT operation_id FROM mirror_integration_requests WHERE project_id=? AND incarnation=? AND workflow_id=? AND journal_id=?",state.projectId,this.readRepositoryIncarnation()??"",workflowId,journalId).toArray()[0];if(old){const saved=await this.mirrorExecutionRecord(old.operation_id,caller);await this.authorizeMirrorExecution(old.operation_id,caller,undefined,undefined,saved.phase==="push_unknown"||saved.phase==="observed"?"reconcile":"dispatch");return saved;}authority.assert();return this.prepareMirrorExecution(crypto.randomUUID(),caller);}
  private mirrorRequestTable(){this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS mirror_execution_requests(project_id TEXT NOT NULL,incarnation TEXT NOT NULL,account_key TEXT NOT NULL,actor_id TEXT NOT NULL,request_id TEXT NOT NULL,operation_id TEXT UNIQUE NOT NULL,PRIMARY KEY(project_id,incarnation,account_key,actor_id,request_id))");}
  async prepareMirrorExecutionRequest(requestId:string,actor:HumanDecisionActor,credentialHash?:string,sessionExpiresAt?:number,expectedTarget?:string){if(!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(requestId))throw Error("Stable mirror request UUID required");const authorize=await this.authorizeRebaseRecovery(actor,credentialHash,sessionExpiresAt),accountKey=await accountKeyFor(actor.userId);authorize();const state=this.load(),incarnation=this.readRepositoryIncarnation();if(!incarnation)throw Error("Mirror incarnation unavailable");this.mirrorRequestTable();const existing=this.ctx.storage.sql.exec<{operation_id:string}>("SELECT operation_id FROM mirror_execution_requests WHERE project_id=? AND incarnation=? AND account_key=? AND actor_id=? AND request_id=?",state.projectId,incarnation,accountKey,actor.userId,requestId).toArray()[0];if(existing){const saved=await this.mirrorExecutionRecord(existing.operation_id,actor,credentialHash,sessionExpiresAt);if(expectedTarget!==undefined&&expectedTarget!==saved.scope.target)throw Error("Original mirror destination differs from this request");await this.authorizeMirrorExecution(saved.scope.id,actor,credentialHash,sessionExpiresAt,saved.phase==="push_unknown"||saved.phase==="observed"?"reconcile":"dispatch");return saved;}if(expectedTarget!==undefined&&(validateMirrorTarget(expectedTarget)!==expectedTarget||this.mirrorConfiguration().target!==expectedTarget))throw Error("Mirror destination changed before request capture");return this.prepareMirrorExecution(crypto.randomUUID(),actor,credentialHash,sessionExpiresAt,requestId,expectedTarget);}
  private mirrorOperationView(saved:MirrorExecutionRecord,canResumeOriginal:boolean,canReconcile:boolean){this.mirrorRequestTable();const request=this.ctx.storage.sql.exec<{request_id:string}>("SELECT request_id FROM mirror_execution_requests WHERE operation_id=?",saved.scope.id).toArray()[0];return{operationId:saved.scope.id,...(request?{requestId:request.request_id}:{}),phase:saved.phase,ref:saved.scope.acceptedRef,commit:saved.scope.commit,tree:saved.scope.tree,target:saved.scope.target,credentialState:saved.credentialRevoked?"revoked" as const:saved.phase==="prepared"?"not_requested" as const:saved.token?"cleanup_pending" as const:"issuance_unknown" as const,nativeState:saved.nativeStopped?"stopped" as const:saved.nativePossible?"unconfirmed" as const:"not_allocated" as const,completed:new MirrorExecutions(this.ctx.storage).complete(saved.scope.id),canResumeOriginal,canReconcile};}
  async mirrorOperationStatus(id:string,actor:HumanDecisionActor,credentialHash?:string,sessionExpiresAt?:number){const saved=await this.mirrorExecutionRecord(id,actor,credentialHash,sessionExpiresAt);let canResumeOriginal=false;try{await this.authorizeMirrorExecution(id,actor,credentialHash,sessionExpiresAt,"dispatch");canResumeOriginal=(saved.phase==="prepared"||saved.phase==="credential_received")&&!saved.nativePossible&&!saved.credentialRevoked;}catch{/* Original approval remains immutable and cannot silently rebind. */}return this.mirrorOperationView(saved,canResumeOriginal,saved.phase==="push_unknown"||saved.phase==="observed");}
  async mirrorOperationStatuses(actor:HumanDecisionActor,credentialHash?:string,sessionExpiresAt?:number,options:{limit?:number;cursor?:string}={}){const authorize=await this.authorizeRebaseRecovery(actor,credentialHash,sessionExpiresAt);authorize();const limit=options.limit??20,cursor=options.cursor??"0";if(!Number.isInteger(limit)||limit<1||limit>20||!/^\d+$/.test(cursor)||!Number.isSafeInteger(Number(cursor)))throw Error("Invalid mirror discovery page");new MirrorExecutions(this.ctx.storage);const state=this.load(),rows=this.ctx.storage.sql.exec<{position:number;id:string}>("SELECT rowid AS position,id FROM mirror_executions WHERE rowid>? AND json_extract(scope,'$.projectId')=? AND json_extract(scope,'$.incarnation')=? AND json_extract(scope,'$.canonicalRepoName')=? ORDER BY rowid LIMIT ?",Number(cursor),state.projectId,this.readRepositoryIncarnation()??"",state.canonicalRepoName,limit+1).toArray(),operations=[];for(const row of rows.slice(0,limit)){operations.push(await this.mirrorOperationStatus(row.id,actor,credentialHash,sessionExpiresAt));authorize();}return{operations,nextCursor:rows.length>limit?String(rows[limit-1]!.position):null,complete:rows.length<=limit};}
