  private mirrorCredentialUsable(id:string):boolean{this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS mirror_execution_credential_validity(id TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,valid_read INTEGER NOT NULL)");const row=this.ctx.storage.sql.exec<{expires_at:number;valid_read:number}>("SELECT expires_at,valid_read FROM mirror_execution_credential_validity WHERE id=?",id).toArray()[0];return !!row&&row.valid_read===1&&row.expires_at>Date.now();}
